-- Sponsors and supporters: offers, committee follow-up, private sponsor links (hashed), listings and partner stockist products.
-- The worker also creates these tables on first use.
CREATE TABLE IF NOT EXISTS club_sponsors(id TEXT PRIMARY KEY,organisation TEXT NOT NULL,contact_name TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',website TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'offer',status TEXT NOT NULL DEFAULT 'new',tier TEXT NOT NULL DEFAULT '',offer_types_json TEXT NOT NULL DEFAULT '[]',participation_json TEXT NOT NULL DEFAULT '[]',offer_text TEXT NOT NULL DEFAULT '',value_cents INTEGER,owner TEXT NOT NULL DEFAULT '',follow_up_on TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',benefits_json TEXT NOT NULL DEFAULT '[]',listing_live INTEGER NOT NULL DEFAULT 0,listing_name TEXT NOT NULL DEFAULT '',listing_blurb TEXT NOT NULL DEFAULT '',listing_url TEXT NOT NULL DEFAULT '',logo TEXT,pending_json TEXT NOT NULL DEFAULT '{}',portal_digest TEXT,portal_issued TEXT,version INTEGER NOT NULL DEFAULT 1,created_utc TEXT NOT NULL,updated_utc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS club_sponsor_products(id TEXT PRIMARY KEY,sponsor_id TEXT NOT NULL REFERENCES club_sponsors(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price_cents INTEGER,url TEXT NOT NULL DEFAULT '',photo TEXT,status TEXT NOT NULL DEFAULT 'pending',created_utc TEXT NOT NULL,updated_utc TEXT NOT NULL);
